# Full working program for JAH-PATH-0001 (flight)
# Stdlib only. Run: python3 program.py
import math
path = {"id": "JAH-PATH-0001", "name": "Al Canyon Carve", "letter": "A", "region": "Jungle Region", "distance_km": 8.8, "skill": "Ace", "craft": "n2", "highlights": "City lights sparkle under the wings at night.", "waypoints": [[947, 1025, 1909], [2454, 2163, 724], [4694, 2528, 1731], [5640, 2523, 2789], [7362, 3329, 1116], [8922, 2539, 2077]], "best_reason": "Captain Siggy's top pick: the perfect mix of beauty, challenge, and smooth flying \u2014 great in any aircraft."}
craft = {"best": "Precision night flying and systems management.", "crew": 2, "desc": "Flies like a shadow. Unstable by design \u2014 the computer helps, but the pilot must stay ahead of it.", "id": "n2", "name": "Night Owl N-2", "range": 5000, "skill": "Ace", "speed": 700, "style": "in the style of a flying-wing stealth aircraft", "type": "Stealth jet"}
def chain_length(wps):
    d = 0.0
    for i in range(len(wps) - 1):
        d += math.sqrt(sum((wps[i+1][k] - wps[i][k]) ** 2 for k in range(3)))
    return round(d, 1)
def flight_minutes():
    return round(path["distance_km"] / craft["speed"] * 60, 1)
def find(text):
    return text.lower() in (path["name"] + " " + path["region"]).lower()
assert len(path["waypoints"]) == 6
assert chain_length(path["waypoints"]) == 10659.5
assert flight_minutes() == 0.8
assert find(path["region"].split()[0])
assert not find("zzzz-no-such-word")
print("program: " + path["id"] + " \u2014 " + path["name"])
print("waypoints: " + str(len(path["waypoints"])))
print("chain length (coordinate units): " + str(chain_length(path["waypoints"])))
print("flight time: " + str(flight_minutes()) + " minutes")
print("self-check: all asserts passed.")

